import{_ as a,o,c as t,a0 as i}from"./chunks/framework.Bmhw_dvp.js";const k=JSON.parse('{"title":"인증","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://dira.proofer.tech/docs/auth"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"dira"}],["meta",{"property":"og:locale","content":"ko_KR"}],["meta",{"property":"og:url","content":"https://dira.proofer.tech/docs/auth"}],["meta",{"property":"og:title","content":"인증"}],["meta",{"property":"og:description","content":"티켓을 큐에 넣으면 cron에 물린 워커가 claude 세션에 넘깁니다. 파일시스템이 곧 큐인 티켓 디스패처."}],["meta",{"property":"og:image","content":"https://dira.proofer.tech/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"name":"twitter:card","content":"summary_large_image"}]]},"headers":[],"relativePath":"docs/auth.md","filePath":"docs/auth.md"}'),s={name:"docs/auth.md"};function c(d,e,n,r,l,p){return o(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="인증" tabindex="-1">인증 <a class="header-anchor" href="#인증" aria-label="Permalink to &quot;인증&quot;">​</a></h1><p>워커가 쓰는 장기 토큰은 Claude 전용입니다. <code>TICKET_ENGINE</code>이 <code>codex</code> 같은 다른 엔진인 워커는 토큰 파일을 보지도 않고 자체 인증을 씁니다(<a href="/docs/worker">워커</a> §<code>엔진</code> 열 참고).</p><h2 id="브라우저로-인증하기" tabindex="-1">브라우저로 인증하기 <a class="header-anchor" href="#브라우저로-인증하기" aria-label="Permalink to &quot;브라우저로 인증하기&quot;">​</a></h2><p>헤더 우측 끝의 톱니(<code>설정</code>) → <code>Claude 인증</code> 섹션. 층이 넷입니다.</p><ol><li><strong>준비물</strong> — <code>claude CLI —</code> 뒤에 앱이 찾은 실행파일 경로가 붙습니다. 못 찾았으면 <code>claude CLI를 찾지 못했습니다 — 워커가 세션을 띄우지 못합니다</code>.</li><li><strong>상태</strong> — <code>인증됨</code>이면 토큰이 놓인 경로와 저장 시각이 한 줄로 나옵니다. 없으면 <code>인증 안 됨 — claude 엔진 워커가 티켓을 물어가지 않습니다</code>.</li><li><strong>발급</strong> — <code>브라우저로 인증하기</code> 버튼.</li><li><strong>직접 넣기</strong> — 이미 토큰이 있는 사람의 칸.</li></ol><p>첫 층이 못 찾았다고 하면 나머지 셋은 소용이 없습니다. 토큰을 받는 것도, 워커가 티켓을 물고 세션을 여는 것도 그 실행파일이 하는 일입니다. 깔려 있는데도 못 찾는다면 앱을 껐다가 다시 여세요. 그래도 그대로면 <a href="/docs/install">설치</a>로 돌아가시면 됩니다.</p><p><code>브라우저로 인증하기</code>를 누르면 앱이 공식 CLI의 발급 절차(<code>claude setup-token</code>)를 대신 밟습니다. 사람이 터미널에 칠 것은 없습니다. CLI가 새 탭을 띄우고, 진행 상황은 버튼 아래 로그로 한 줄씩 뜹니다.</p><ul><li>브라우저가 코드를 보여주면 그 코드를 다이얼로그의 칸에 붙여 넣으세요. 승인만으로 끝나는 경우도 있습니다. 그 맥이 이미 claude.com에 로그인·동의된 상태면 코드 없이 흘러갑니다. 칸은 물을 때 답하는 자리입니다.</li><li>토큰은 앱이 제자리에 저장합니다. 사람이 옮겨 적을 것이 없어서 진행 로그에서는 토큰을 가려서 보여줍니다. 화면 공유나 스크린샷에 원문이 남지 않습니다.</li><li>누르는 순간이 이미 발급입니다. 브라우저가 열렸다면 사용자의 Claude 계정으로 자격증명이 만들어지는 흐름이 시작된 것이고, 되돌리는 자리는 없습니다.</li><li>깨지면 사유를 그대로 보여줍니다. 앱이 하는 일은 남의 CLI 화면을 읽는 것이라 그쪽 문구가 바뀌면 깨질 수 있습니다. 그때 바닥이 되는 것이 마지막 층입니다.</li></ul><p><code>직접 넣기</code>는 발급이 된 뒤에도 남아 있습니다. 이미 받아 둔 토큰을 붙여 넣고 <code>저장</code>을 누르면 같은 자리에 같은 권한으로 씁니다. 다시 저장하면 덮어씁니다. 토큰은 하나뿐이라 이력을 남길 자리가 없습니다.</p><p>검증은 두 가지만 봅니다. 비어 있지 않은지, 공백이나 개행이 섞이지 않았는지. 접두사 형식으로는 거르지 않습니다. 그 형식은 우리 것이 아니고, 바뀌면 멀쩡한 토큰을 거부하게 됩니다. 그래서 화면은 <code>저장했습니다. 유효한지는 다음 디스패치에서 드러납니다</code>까지만 말합니다.</p><h2 id="알림-종-—-토큰이-없을-때-뜨는-첫-항목" tabindex="-1">알림 종 — 토큰이 없을 때 뜨는 첫 항목 <a class="header-anchor" href="#알림-종-—-토큰이-없을-때-뜨는-첫-항목" aria-label="Permalink to &quot;알림 종 — 토큰이 없을 때 뜨는 첫 항목&quot;">​</a></h2><p>&quot;워커가 도는데 아무것도 안 한다&quot;를 겪기 전에 화면이 먼저 말해 줍니다. 프로젝트 화면 헤더의 알림 종에 첫 항목으로 뜹니다. <code>Claude 토큰이 없습니다</code> · <code>워커가 티켓을 집어도 세션을 못 열고 그대로 끝냅니다.</code> 그 항목의 <code>토큰 저장</code> 버튼이 그 자리에서 위 다이얼로그를 엽니다. 화면을 옮길 일이 없습니다.</p><ul><li>톱니 버튼 자체도 바뀝니다. 아이콘 옆에 <code>인증 필요</code>가 붙어서, 두 화면 어디에 있든 보입니다.</li><li>claude 워커가 하나도 없는 프로젝트에는 안 뜹니다. 다만 워커를 못 읽었으면 띄웁니다. 판정 불가를 &quot;괜찮다&quot;로 바꿔 버리면 이 장이 닫으려는 침묵이 그대로 돌아오기 때문입니다.</li><li>닫는 버튼이 없습니다. 토큰이 놓이면 판정이 저절로 꺼집니다.</li><li>만료는 예고하지 못합니다. 만료 시각이 파일에 안 적혀 있고 CLI도 알려주지 않습니다. 대신 만료된 뒤의 침묵은 종의 다음 항목(<code>세션이 열리자마자 죽는 워커</code>)이 깹니다. <a href="/docs/screens">화면 소개</a>를 참고하세요.</li></ul><h2 id="클라우드-마운트-—-전체-디스크-접근-권한" tabindex="-1">클라우드 마운트 — 전체 디스크 접근 권한 <a class="header-anchor" href="#클라우드-마운트-—-전체-디스크-접근-권한" aria-label="Permalink to &quot;클라우드 마운트 — 전체 디스크 접근 권한&quot;">​</a></h2><p>큐 루트가 구글드라이브 같은 마운트에 있을 때만 해당합니다. macOS는 cron이 띄운 프로세스가 보호된 위치의 파일을 읽으려 하면 <strong>에러도 없이 조용히 막습니다.</strong> 파일이 없는 것처럼 보입니다.</p><p><code>설정 › 개인정보 보호 및 보안 › 전체 디스크 접근 권한</code>을 여세요. 목록에 <code>cron</code> 자체는 뜨지 않으므로 <code>+</code>를 누른 뒤 <code>Cmd+Shift+G</code>로 <code>/usr/sbin/cron</code>을 직접 입력해 추가하시면 됩니다. 실제로 파일을 읽는 것은 워커 스크립트가 아니라 그걸 띄우는 cron 데몬이기 때문입니다. 켠 뒤에도 곧바로 반영되지 않을 수 있으니, 워커 화면에서 한 번 직접 돌려 큐가 제대로 보이는지 확인하세요.</p><h2 id="앱-관리-—-워커를-만들-때마다-묻는-권한" tabindex="-1"><code>앱 관리</code> — 워커를 만들 때마다 묻는 권한 <a class="header-anchor" href="#앱-관리-—-워커를-만들-때마다-묻는-권한" aria-label="Permalink to &quot;`앱 관리` — 워커를 만들 때마다 묻는 권한&quot;">​</a></h2><p>워커를 추가하면 앱이 crontab에 줄을 쓰고, 그때 macOS가 <code>앱 관리</code> 권한을 묻습니다. 응답 전까지 등록은 멈춰 있고, <code>허용</code>을 누르면 그 등록은 끝까지 갑니다. 문제는 이 승인이 다음 등록까지 남지 않는다는 것입니다. 워커를 하나 더 만들 때마다 같은 창이 또 뜹니다 (<a href="/docs/concurrency">동시에 몇 개 돌릴까</a>). 미리 켜 두거나 확인하는 자리는 <code>설정 › 개인정보 보호 및 보안 › 앱 관리</code>입니다.</p><h2 id="앱-없이-—-엔진만-쓸-때" tabindex="-1">앱 없이 — 엔진만 쓸 때 <a class="header-anchor" href="#앱-없이-—-엔진만-쓸-때" aria-label="Permalink to &quot;앱 없이 — 엔진만 쓸 때&quot;">​</a></h2><p>앱을 안 쓰고 <code>tick.sh</code>만 돌린다면 위 다이얼로그가 하는 일을 손으로 해야 합니다. 결과물은 똑같은 파일 하나입니다. 터미널을 열고 세 줄을 차례로 입력하세요.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.config/dira</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setup-token</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">printf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> %s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;&lt;토큰&gt;&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.config/dira/oauth-token</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 600</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.config/dira/oauth-token</span></span></code></pre></div><p><code>claude setup-token</code>이 낸 토큰을 <code>~/.config/dira/oauth-token</code>에 <strong>개행 없이 한 줄로</strong> 적고 <code>chmod 600</code>으로 소유자만 읽게 잠그는 것입니다. 앱이 저장하는 자리와 같은 경로라, 어느 쪽으로 넣든 워커는 같은 파일을 읽습니다.</p><p><strong>토큰은 머신 로컬에 하나만 둡니다.</strong> 큐 루트가 공유 드라이브에 있어도 <code>~/.config/dira</code>는 동기되지 않는 이 머신만의 자리입니다. 큐를 옮기거나 공유해도 비밀이 같이 퍼지지 않는 이유가 이것입니다. 워커를 여러 머신에서 돌린다면 머신마다 따로 받으셔야 합니다.</p><p>다음은 <a href="/docs/troubleshooting">트러블슈팅</a>입니다.</p>',24)])])}const g=a(s,[["render",c]]);export{k as __pageData,g as default};
